update pages set contenu = '{"gabarit":"editorial","chapeau":"Certaines décisions ne se prennent pas dans un article de blog : externaliser sa maintenance, garder ou remplacer une machine. Ces dossiers de fond prolongent notre [guide maintenance industrielle](/ressources/) avec une grille de décision claire, critère par critère, à emporter en réunion de direction.","blocs":[]}'::jsonb where path = '/ressources/livres-blancs/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"citation","texte":"Chaque livre blanc est construit sur le terrain, machine par machine, par des équipes qui vivent ces arbitrages chaque année. Pas de discours commercial : des faits pour trancher."},{"type":"titre","niveau":2,"texte":"Décider avec méthode","id":"decider-avec-methode"},{"type":"paragraphe","texte":"Deux dossiers pour les choix qui engagent votre outil de production, sans céder à l''intuition."},{"type":"liste","items":[{"accroche":"Confier sans lâcher","texte":"Le [Livre blanc : externaliser sa maintenance sans perdre la main](/ressources/livres-blancs/externaliser-sa-maintenance/) pose les garde-fous qui gardent la connaissance du parc chez vous."},{"accroche":"Rénover ou racheter","texte":"Le livre blanc [retrofit ou remplacement](/ressources/livres-blancs/retrofit-ou-remplacement/) donne la grille économique pour arbitrer une machine vieillissante, critère par critère."}]},{"type":"titre","niveau":2,"texte":"Comment s''en servir","id":"comment-s-en-servir"},{"type":"paragraphe","texte":"Un livre blanc n''est pas une brochure : c''est un outil de travail pour la réunion où la décision se prend."},{"type":"liste","items":[{"accroche":"Poser le cadre","texte":"Chaque dossier liste les critères à examiner avant de trancher. Vous partez d''une base commune, pas d''un avis."},{"accroche":"Confronter les scénarios","texte":"Les deux options sont mises face à face, coûts et risques compris. Le choix se fait sur des faits, pas sur une impression."},{"accroche":"Passer à l''action","texte":"Une fois la décision prise, nos techniciens la mettent en œuvre sur site. Le dossier théorique devient un chantier suivi."}]},{"type":"citation","texte":"Un arbitrage à trancher, un dossier à challenger ? Nos techniciens font le diagnostic sur site : appelez le 04 78 33 72 05, un chargé d''affaires vous rappelle dans l''heure."},{"type":"citation","texte":"À lire aussi : [Ressources : Articles](/ressources/articles/)"},{"type":"citation","texte":"[Demander un diagnostic maintenance](/contact/)"}]'::jsonb) where path = '/ressources/livres-blancs/';
